function generateDayWiseTimeSeries2(baseval, count, yrange) {
  let i = 0;
  let series2 = [];
  while (i < count) {
    let x = baseval;
    let y = Math.floor(Math.random() * (yrange.max - yrange.min + 1)) + yrange.min;
    series2.push([x, y]);
    baseval += 864e5;
    i++;
  }
  return series2;
}
